def dutConnet(dutInfo,maxRetryTimes=20,retryInterval=10):
    tel = TelnetClient()
    for i in range(maxRetryTimes):
        if tel.login_host(dutInfo["ip"],dutInfo["UserName"],dutInfo["PassWord"],dutInfo['port']):
            return tel #连接成功则返回TelnetClient对象
        else:
            sleep(retryInterval) #连接失败重连间隔时间
    return False #返回失败值


class Worker(QThread):
    logSignal = pyqtSignal(int)
    
    def __init__(self,textEdit,logFn,maxNum):
        super(Worker,self).__init__()
        self.version = '2.34'
        self.stopped = False
        self.t = textEdit
        self.f = logFn
        self.n = int(maxNum)

    def run(self):
        # sleep(3)
        try:
            while not self.stopped:
                # 检查行数
                line_count = self.t.document().blockCount()
                if line_count > self.n:
                    # 发送信号以清空文本
                    txt = self.t.toPlainText()
                    self.logSignal.emit(0)
                    writeCfgTxt(txt,self.f,mode='a+')
                # 等待一段时间再继续检查
                self.msleep(1000)
        except Exception as e:
            print(e)

    def stop(self):
        self.stopped = True


class MainThread(QThread):
    signal = pyqtSignal()

    def __init__(self, target=None):
        super().__init__()
        self.target = target
        
    def run(self):
        if self.target:
            self.target()
        self.is_running = True
            
    def stop(self):
        self.is_running = False
        self.terminate()

class getAreaThread(QThread):
    finished_signal = pyqtSignal()
    result_signal = pyqtSignal(str)  # 新增结果信号
    error_signal = pyqtSignal(str)  # 新增错误信号
    def __init__(self, parent=None):
        super().__init__(parent)
        self.result = None  # 存储结果

    def run(self):
        # 执行耗时操作
        try:
            result = getAreaTupleFunc()
            self.result = result  # 存储结果
            self.result_signal.emit(result)  # 发送结果信号
        except Exception as e:
            self.error_signal.emit(f"坐标获取失败: {str(e)}")
        finally:
            self.finished_signal.emit() # 发送完成信号


