    #log重定向   
    def outputWritten(self, text):
        cursor = self.logText.textCursor() #获得指针对象
        cursor.movePosition(QtGui.QTextCursor.End)
        cursor.insertText(text)
        self.logText.setTextCursor(cursor)
        self.logText.ensureCursorVisible()

    #拷机参数表格操作
    def actAdd(self):
        try: 
            row = self.actTableWidget.currentRow() #获取当前选中行
            self.actTableWidget.insertRow(row+1) #在当前选中行的下一行添加新行（默认为主备切换）
            self.actTableWidget.setCellWidget(row+1, 0, actionCombox(self.actionChanged))
            self.actTableWidget.setCellWidget(row+1, 1, myLineEdit())
            self.actTableWidget.setCellWidget(row+1, 2, myLineEdit())
            self.actTableWidget.setCellWidget(row+1, 3, actTimesSpinBox())
            self.actTableWidget.setCellWidget(row+1, 4, waitTimeLineEdit())
        except Exception as e:
            print(e)

    def actDel(self):
        row = self.actTableWidget.currentRow() #获取当前选中行
        self.actTableWidget.removeRow(row) #删除当前行
        self.actTableWidget.selectRow(-1) #选中新行

    def actClr(self):
        self.actTableWidget.setRowCount(0)
        self.actTableWidget.clearContents()

    def actMvDown(self):
        try:
            if self.actTableWidget.rowCount() == 1:
                return
            row = self.actTableWidget.currentRow()
            column = self.actTableWidget.currentColumn()
            
            if row < self.actTableWidget.rowCount()-1:
                #print(row)
                actionName  = self.actTableWidget.cellWidget(row,0)
                arg1 = self.actTableWidget.cellWidget(row,1)
                arg2 = self.actTableWidget.cellWidget(row,2)
                times = self.actTableWidget.cellWidget(row,3)
                wt = self.actTableWidget.cellWidget(row,4)
                self.actTableWidget.insertRow(row+2)
                #第一列
                self.actTableWidget.setCellWidget(row+2,0,actionName)
                #self.actTableWidget.cellWidget(row+2,0).setCurrentText(actionName)
                #第二列
                self.actTableWidget.setCellWidget(row+2,1,arg1)
                #self.actTableWidget.cellWidget(row+2,1).setText(arg1)
                #第三列
                self.actTableWidget.setCellWidget(row+2,2,arg2)
                #self.actTableWidget.cellWidget(row+2,2).setText(arg2)
                #第四列
                self.actTableWidget.setCellWidget(row+2,3,times)
                self.actTableWidget.setCellWidget(row+2,4,wt)
                #self.actTableWidget.cellWidget(row+2,3).setText(wt)
                #选中行
                self.actTableWidget.setCurrentCell(row+2,column)
                #删除原先行
                self.actTableWidget.removeRow(row)  
        except Exception as e:
            print(e)

    def actMvUp(self):
        try:
            row = self.actTableWidget.currentRow()
            column = self.actTableWidget.currentColumn()
            if row > 0:
                actionName  = self.actTableWidget.cellWidget(row,0)
                arg1 = self.actTableWidget.cellWidget(row,1)
                arg2 = self.actTableWidget.cellWidget(row,2)
                times = self.actTableWidget.cellWidget(row,3)
                wt = self.actTableWidget.cellWidget(row,4)
                self.actTableWidget.insertRow(row-1)
                #第一列
                self.actTableWidget.setCellWidget(row-1,0,actionName)
                #self.actTableWidget.cellWidget(row-1,0).setCurrentText(actionName)
                #第二列
                self.actTableWidget.setCellWidget(row-1,1,arg1)
                #self.actTableWidget.cellWidget(row-1,1).setText(arg1)
                #第三列
                self.actTableWidget.setCellWidget(row-1,2,arg2)
                #self.actTableWidget.cellWidget(row-1,2).setText(arg2)
                #第四列
                self.actTableWidget.setCellWidget(row-1,3,times)
                self.actTableWidget.setCellWidget(row-1,4,wt)
                #self.actTableWidget.cellWidget(row-1,3).setText(wt)
                #选中行
                self.actTableWidget.setCurrentCell(row-1,column)
                #删除原先行
                self.actTableWidget.removeRow(row+1)
        except Exception as e:
            print(e)

