    def getAreaDict(self):
        try:
            d = {}
            for i in range(self.areaTableWidget.rowCount()):
                d[i] = {
                        "areaTuple":self.areaTableWidget.cellWidget(i,0).text(),
                        "expectSec":self.areaTableWidget.cellWidget(i,1).currentText(),
                        "expectValue":self.areaTableWidget.cellWidget(i,2).text(),
                        "note":self.areaTableWidget.cellWidget(i,3).text()
                        }
            return d
        except Exception as e:
            #print(e)
            return {}
       
    def getActDict(self):
        try:
            d = {}
            for i in range(self.actTableWidget.rowCount()):
                d[i] = {
                        "action":getQwidgetValue(self.actTableWidget.cellWidget(i,0)),
                        "arg_1":getQwidgetValue(self.actTableWidget.cellWidget(i,1)),
                        "arg_2":getQwidgetValue(self.actTableWidget.cellWidget(i,2)),
                        "times":getQwidgetValue(self.actTableWidget.cellWidget(i,3)),
                        "waitFor":getQwidgetValue(self.actTableWidget.cellWidget(i,4))
                        }
            return d
        except Exception as e:
            print(e)
            return {}
        
    def getDutInfo(self):
        dutInfoDict = {}
        ipText = self.dutIP.text()
        if '-' in ipText:
            dutInfoDict['ip'] = ipText.split('-')[0]
            dutInfoDict['port'] = ipText.split('-')[1]
        else:
            dutInfoDict['ip'] = ipText
            dutInfoDict['port'] = '23'
        
        dutInfoDict["UserName"] = self.dutUn.text()
        dutInfoDict["PassWord"] = self.dutPw.text()
        #timePrint(dutInfoDict)
        return dutInfoDict
    
