    @error_handler
    def actionStart(self):
        #【前置操作】
        #创建相关文件夹
        # createFloder('data')
        # createFloder('areaData')
        # createReportXls()
        # self.dataFn = createFloder(datetime.now().strftime('data/{}_%Y%m%d%H%M%S'.format(self.dutInfo['ip'])))
        # self.logFn = path.join(self.dataFn,'log.log')
        
        actionResult = True
        self.doneTimes = 0
        self.passTimes = 0
        self.isReport = False
        # self.actionTimesDict = {}
        
        #检查report.xls是否处于打开状态，若是则打印告警信息：
        if is_file_open(reportFn):
            print(f"Warning:检测到{reportFn}处于打开状态，会导致拷机报告更新失败，请在拷机停止之前关闭该文件。")


        #等待拷机开始时间
        self.logOpenButton.setDisabled(True)
        waitForStart = int(self.waitForMain.text()) * 60
        if waitForStart:
            for t in range(waitForStart,0,-1):
                self.StatusLabel.setText(f"{t}s后开始拷机")
                sleep(1)
        #print(f'log将自动保存，路径:{self.logFn}')

        #【连接设备】
        self.StatusLabel.setText(f"连接设备中...")
        timePrint('开始连接设备...')
        self.mainTel = dutConnet(self.dutInfo)
        
        if not self.mainTel:
            timePrint("设备登录失败！")
            self.StatusLabel.setText(f"自动停止，请点击停止按钮结束拷机")
            return False
        
        self.StatusLabel.setText(f"收集设备初始信息...")
        
        if 'configCheck' in self.actionList:
            writeCfgTxt(self.mainTel.getCfgTxt(),path.join(self.dataFn,'cfg.txt'))

        if 'portStatusCheck' in self.actionList:
            self.portStatusDft = self.mainTel.getPortStatus()
        
        if 'slotStatusCheck' in self.actionList:
            self.slotStatusDft = self.mainTel.getAllSlotStatus()

        if 'fanStatusCheck' in self.actionList:
            self.fanStatusDft = self.mainTel.getFanStatus()

        if 'powerStatusCheck' in self.actionList:
            self.powerStatusDft = self.mainTel.getPowerStatus()

        if 'internalPortStatusCheck' in self.actionList:
            self.internalPortStatusDft = self.mainTel.getInternalPortStatus()

        if 'intfUsageCheck' in self.actionList:
            self.portUsageDft = self.mainTel.getAllPortUsage()

        #【开始拷机动作】
        #self.mainTel.do_cmd_noprint('ter no mo')  #关闭log打印

        mainTimes = 14159265358979 if self.isInfinitely.isChecked() else int(self.mainTimes.text())
        for actTimes in range(1,mainTimes + 1):
            # if not actionResult:
            #     break
            finalResult = True
            errorStep = {}
            for k,v in self.actionDict.items():
                # if not actionResult:
                #     break
                #【设备操作】
                #主备切换
                actionCn = v.get('action')
                action = actionNameDict.get(actionCn)
                times = int(v.get('times')) if v.get('times') else 0
                self.StatusLabel.setText(f"正在进行第{actTimes}轮拷机-第{k+1}步-{actionCn}")
                for _ in range(times):
                    if action == 'dutRedu':
                        self.mainTel.reduReady()
                        self.mainTel.do_Redu()
                        del self.mainTel
                        sleep(float(self.reduRcTime.text()))
                        self.mainTel = dutConnet(self.dutInfo) #重连
                        self.mainTel.waitForBackup()  #等待备机状态

                    #整机重启
                    if action == 'dutReload':
                        self.mainTel.do_Reload()
                        del self.mainTel
                        sleep(float(self.reloadRcTime.text()))
                        self.mainTel = dutConnet(self.dutInfo) 

                    #配置下发
                    if action == 'dutConfig':
                        self.mainTel.configFlapAction(path.join(self.dutCfgFr,v.get('arg_1').strip()),v.get('arg_2'))

                    #进程重启
                    if action == 'dutPkill':
                        self.mainTel.pkillAction(v.get('arg_1'),v.get('arg_2'))

                    #线卡上电
                    if action == 'slotPowerOn':
                        self.mainTel.powerOnAction([i.strip() for i in v.get('arg_1').split(',')],v.get('arg_2'))

                    if action == 'slotPowerOnNoWaitUp':
                        self.mainTel.powerOnAction([i.strip() for i in v.get('arg_1').split(',')],v.get('arg_2'),waitForUp=False)
                    
                    #线卡下电
                    if action == 'slotPowerOff':
                        self.mainTel.powerOffAction([i.strip() for i in v.get('arg_1').split(',')],v.get('arg_2'))
                    
                    #线卡Reset
                    if action == 'slotReset':
                        self.mainTel.resetSlotAction([i.strip() for i in v.get('arg_1').split(',')],v.get('arg_2'))
                    
                    if action == 'slotResetNoWaitUp':
                        self.mainTel.resetSlotAction([i.strip() for i in v.get('arg_1').split(',')],v.get('arg_2'),waitForUp=False)

                #【检查项】
                if action == 'coredumpCheck':
                    actionResult = self.mainTel.coredumpCheck()
                        
                if action == 'configCheck':
                    cfgNameNow = f'cfg_{getTimeStampNow()}.txt'
                    showRunTxt = self.mainTel.getCfgTxt()
                    writeCfgTxt(showRunTxt,path.join(self.dataFn,cfgNameNow))
                    actionResult = cfgCompare(path.join(self.dataFn,'cfg.txt'),path.join(self.dataFn,cfgNameNow))          

                if action == 'portUsageCheck':
                    portList = [port.strip() for port in v.get('arg_1').split('\n') if port.strip()]
                    actionResult = self.mainTel.ucmpCheck(portList,mode=v.get('arg_2'))

                if action == 'momCheck':
                    actionResult = self.mainTel.getMomInfoFlap(self.momWlFn)

                if action == 'areaCheck':
                    actionResult = self.runAreaCheck()
                
                if action == 'portStatusCheck':
                    actionResult = portStatusCheck(self.portStatusDft,self.mainTel.getPortStatus())

                if action == 'slotStatusCheck':
                    actionResult = slotStatusCheck(self.slotStatusDft,self.mainTel.getAllSlotStatus())

                if action == 'internalPortStatusCheck':
                    actionResult = portStatusCheck(self.internalPortStatusDft,self.mainTel.getInternalPortStatus())
                        
                if action == "showInfoCheck":
                    actionResult = self.mainTel.showInfoCheck(v.get('arg_1').strip(),v.get('arg_2'))

                if action == "showNoInfoCheck":
                    actionResult = self.mainTel.showInfoCheck(v.get('arg_1').strip(),v.get('arg_2'),isExist=False)

                if action == 'nsrCheck':
                    actionResult = self.mainTel.nsrCheck(v.get('arg_1').split(','))

                if action == 'fanStatusCheck':
                    actionResult = fanStatusCheck(self.fanStatusDft,self.mainTel.getFanStatus())
                
                if action == 'powerStatusCheck':
                    actionResult = powerStatusCheck(self.powerStatusDft,self.mainTel.getPowerStatus())

                if action == 'intfUsageCheck':
                    portList = [port.strip() for port in v.get('arg_1').split('\n') if port.strip()]
                    actionResult = portUsageCheck(self.portUsageDft,self.mainTel.portListUsage(portList),mode=v.get('arg_2'))

                if action == 'slotCpuCheck':
                    actionResult = thresCheck(self.mainTel.getSlotCPUInfo(),float(self.CPUErrorThreshold.text()),name='线卡CPU占用')
                
                if action == 'slotMemoryCheck':
                    actionResult = thresCheck(self.mainTel.getSlotMemoryInfo(),float(self.MemoryErrorThreshold.text()),name='线卡内存占用')

                if action == 'emmcCheck':
                    actionResult = thresCheck(self.mainTel.getEmmcInfo(),float(self.EMMCErrorThreshold.text()),name='线卡ECCM寿命',mode='lt')

                if action == 'selfHealingCheck':
                    actionResult = self.mainTel.selfHealingCheck()
                
                if action == 'clutserCheck':
                    actionResult = clusterStatusCheck(self.mainTel.getClusterInfo())
                
                if action == 'exceptionCheck':
                    actionResult = self.mainTel.exceptionCheck()

                if not actionResult:
                    finalResult = False
                    errorStep[str(k+1)] = actionCn
                
                isOverFlag = (not finalResult) and (self.isFailStopCB.isChecked())
                # print(isOverFlag)

                #检查项Fail，退出for循环
                if isOverFlag:
                    break
                else:
                    waitForNextAct = int(v.get('waitFor'))
                    if waitForNextAct:
                        for t in range(waitForNextAct,0,-1):
                            self.StatusLabel.setText(f"正在进行第{actTimes}轮拷机-第{k+1}步-{actionCn}-{t}s后执行下一操作")
                            sleep(1)
                    #sleep(float(v.get('waitFor')))
                    
            #退出外层for循环
            self.doneTimes += 1
            timePrint(f'第{actTimes}轮拷机结束，结果:【{resultDict[finalResult]}】')
            
            #统计：
            if finalResult:
                self.passTimes += 1

            if errorStep:
                print(f"检查项错误步骤:")
                printDict(errorStep,'-')
                fsLink = self.feiShuLink.text().strip()
                if fsLink:
                    try:
                        robot = FeishuTalk(fsLink)
                        robot.sendFailText(self.description,self.dutInfo.get('ip'),str(actTimes),errorStep)
                    except Exception as e:
                        print(e)
            
            if isOverFlag:
                # self.StatusLabel.setText(f"自动停止。。")
                timePrint('检查到Fail项，拷机自动停止！')
                break
        
        if actTimes == mainTimes:
            timePrint("拷机已达最大次数，自动停止。")
        
        # writeResultTxt(self.actionTimesDict,path.join(self.dataFn,'result.txt'))
        self.reportUpdate()

        #一键收集
        if (not finalResult) and (self.isFailCollectCB.isChecked()):
            self.StatusLabel.setText(f"一键收集中...")
            self.mainTel.dutCollect()

        self.StatusLabel.setText(f"自动停止，请点击停止按钮结束拷机")

    @error_handler
    def runMain(self):
        #【前置操作】
        #创建相关文件夹
        createFloder('data')
        createFloder('areaData')
        createFloder('dutCfg')
        createReportXls()

        self.dataFn = createFloder(datetime.now().strftime('data/{}_%Y%m%d%H%M%S'.format(self.dutIP.text())))
        self.logFn = path.join(self.dataFn,'log.log')
        createMoudleFile('dutCfg/配置下发说明.txt')
        # createMoudleFile('dutCfg/延时配置模板.txt')
        #获取设备信息并检查合法性
        self.dutCfgFr = self.dutCfgFrLE.text()
        self.momWlFn = self.momWlFnLE.text()
        errorCheckList = []

        try:
            self.dutInfo = self.getDutInfo()
            IPv4Address(self.dutInfo.get('ip'))
        except ValueError as e:
            errorCheckList.append('【设备信息】IP地址格式错误。')
        except Exception as e:
            print(e)
        
        #拷机描述
        self.description = self.descriptionLineEdit.text().strip()
        if not self.description:
            errorCheckList.append('【拷机设置】拷机描述不能为空。')
        #获取拷机参数并检查合法性
        self.actionDict = self.getActDict()
        if not self.actionDict:
            errorCheckList.append('【拷机设置】请添加拷机动作。')
        else:
            errorCheckList += actionDictCheck(self.actionDict,self.dutCfgFr)
        
        
        #获取监控区域参数并检查合法性，拷机设置中带有监控区域检查时才执行
        self.actionList = getActionsList(self.actionDict)
        if 'areaCheck' in self.actionList:
            self.areaDict = self.getAreaDict()
            if not self.areaDict:
                errorCheckList.append('【区域设置】请添加监控区域。')
            else:
                errorCheckList += areaDictCheck(self.getAreaDict())

        #mom白名单路径确定
        if 'momCheck' in self.actionList:
            if not fileRouteCheck(self.momWlFn):
                errorCheckList.append(f'【其他设置】0消息白名单文件{self.momWlFn}不存在，请重新选择文件。')
            
        
        if errorCheckList:
            print("请检查以下参数：")
            printList(errorCheckList,seq=True)
            rmdir(self.dataFn)
            self.logOpenButton.setDisabled(True)
            return 
        
        self.disableInput()
        self.clearAreaResults()
        #开始拷机线程
        self.mainThread = MainThread(target=self.actionStart)
        self.logWorker = Worker(self.logText,self.logFn,self.logMaxNum.text())
        self.logWorker.logSignal.connect(self.logTextClear)
        self.mainThread.start()
        self.logWorker.start()  
        # self.logThread.start()

