    @error_handler
    def runAreaCheck(self):
        errorList = [] #元素{'msg':xxx',imagPath':xx}\
        #self.statusLable.setText("正在获取监控数值。。")
        
        for k,v in self.areaDict.items():
            areaTuple = eval(v.get("areaTuple"))
            expectSec = expectDict[v.get("expectSec")]
            expectValue = int(v.get("expectValue"))
            note = v.get("note").strip()
            areaKnownAs = note if note else str(areaTuple)

            #判定预期值,最多判断3次
            for i in range(3):
                picFn = getAreaPic(areaTuple)
                ocrDigitResult = doOcr(picFn,self.psmCombox.currentText())
                if expectSec == 'ltbfe':
                    if ocrDigitResult != None:
                        try:
                            lastNum = int(getQwidgetValue(self.areaTableWidget.cellWidget(k,5)))
                        except:
                            lastNum = 0
                        minusResult =  ocrDigitResult - lastNum
                        judgeResult = (minusResult >= 0) and (minusResult <= expectValue)
                    else:
                        judgeResult = False
                else:
                    judgeResult = digitJudge(ocrDigitResult,expectValue,mode=expectSec)
                
                if judgeResult:
                    break
                else:
                    sleep(2)
                       
            #3次判断失败，取最后一次的值
            self.areaTableWidget.cellWidget(k,4).setPixmap(QPixmap(picFn))
            self.areaTableWidget.cellWidget(k,5).setText(str(ocrDigitResult))
            
            if not judgeResult:
                errorList.append({'msg':'区域【{}】的监控值为【{}】,与预期不符。(预期值:【{}】，与预期关系:【{}】)\n'.format(areaKnownAs,str(ocrDigitResult),str(expectValue),v.get("expectSec")),'imagPath':picFn})
                self.areaTableWidget.cellWidget(k,5).setStyleSheet("background-color:rgb(217,76,49)") #217;76;49
            else:
                self.areaTableWidget.cellWidget(k,5).setStyleSheet("background-color:rgb(146,208,80)") #146,208,80

        if errorList:
            fsLink = self.feiShuLink.text().strip()
            if fsLink:
                try:
                    robot = FeishuTalk(fsLink)
                    robot.sendTextMsgList(errorList)
                except Exception as e:
                    print(e)
        
        return len(errorList) == 0
    
    @error_handler
    def stopMain(self):
        try:
            self.mainTel.logout_host()
            del self.mainTel
        except Exception as e:
            pass

        try:
            self.logWorker.stop()
            del self.logWorker
        except Exception as e:
            pass
        
        try:
            self.mainThread.stop()
            del self.mainThread
            timePrint("拷机停止...")
        except AttributeError as e:
            print(e)
        finally:
            self.enableInput()
            self.StatusLabel.setText(f"未运行")
            self.reportUpdate()

        try:
            self.writeRestLog()
            self.logOpenButton.setEnabled(True)
        except:
            pass

        
    @error_ignore
    def getAreaTp(self):
        """线程安全的坐标获取方法"""
        try:
            self.disableInput()
            self.stopButton.setEnabled(False)
            self.logText.clear()
            
            # 停止现有线程
            if hasattr(self, 'current_thread') and self.current_thread.isRunning():
                self.current_thread.quit()
                self.current_thread.wait()
            
            # 创建线程
            t = getAreaThread()
            
            # 连接完成信号
            t.finished_signal.connect(self._on_area_thread_finished)
            
            # 连接结果信号
            t.result_signal.connect(self._on_area_thread_result)
            
            # 连接错误信号
            t.error_signal.connect(self._on_area_thread_error)
            
            # 将线程对象保存为实例变量，避免被垃圾回收
            self.current_thread = t
            t.start()
            
        except Exception as e:
            print(f"启动坐标获取线程失败: {e}")
            self.enableInput()
            self.stopButton.setEnabled(True)
        
        
    # 坐标获取线程的回调方法
    def _on_area_thread_finished(self):
        """坐标获取线程完成的回调"""
        try:
            self.enableInput()
            self.stopButton.setEnabled(True)
        except Exception as e:
            print(f"坐标获取完成处理失败: {e}")

    def _on_area_thread_result(self, result):
        """坐标获取线程结果的回调"""
        try:
            # 存储结果到实例变量
            self.thread_result = result
            
            # 自动将结果填充到lineedit上
            if result is not None:
                self.ocrTupleLineEdit.setText(str(result))
            else:
                print('选择已取消')
                
        except Exception as e:
            print(f"坐标获取结果处理失败: {e}")

    def _on_area_thread_error(self, error_msg):
        """坐标获取线程错误的回调"""
        try:
            print(f"坐标获取错误: {error_msg}")
            self.ocrTupleLineEdit.setText(f'坐标获取失败: {error_msg}')
        except Exception as e:
            print(f"坐标获取错误处理失败: {e}")

    def reportUpdate(self):
        # getActionDictXls(reportFn)
        if self.isReport:
            return
        if not self.doneTimes:
            return
        upgradeInfo = {self.description:(self.doneTimes,self.passTimes)}
        # doneDict = self.actionTimesDict
        xlsDict = getActionDictXls(reportFn)
        # finalDict = {}
        # finalDict.update(xlsDict)
        if xlsDict.get(self.description):
            xlsDict[self.description] = tuple([sum(x) for x in zip(xlsDict[self.description], upgradeInfo[self.description])])
        else:
            xlsDict[self.description] = upgradeInfo[self.description]

        print("本次拷机执行轮次:{}, PASS次数:{}, PASS率:{:.2%}".format(self.doneTimes,self.passTimes,self.passTimes/self.doneTimes))
        try:
            writeXlsDict(xlsDict,reportFn)
            print(f"结果已更新至{os.path.abspath(reportFn)}")
        except:
            print(f"拷机报告更新失败！拷机停止之前请关闭{os.path.abspath(reportFn)}！")
        self.isReport = True

