    def getCurOption(self):
        actSet = {"mainTimes":int(self.mainTimes.text()),
                "isInfinitely":self.isInfinitely.isChecked(),
                "isFailCollect":self.isFailCollectCB.isChecked(),
                'isFailStop':self.isFailStopCB.isChecked(),
                'ismainTimes':self.mainTimes.isEnabled(),
                'description':self.descriptionLineEdit.text().strip()}
        
        if actSet.get("isInfinitely"):
            actSet['ismainTimes'] = False
        else:
            actSet['ismainTimes'] = True
        
        return actSet
    
    # OCR测试专用信号类
    class OCRTestSignals(QObject):
        update_result = pyqtSignal(str)  # 更新识别结果
        update_image = pyqtSignal(str)   # 更新图片
        update_status = pyqtSignal(bool) # 更新按钮状态
        show_error = pyqtSignal(str)     # 显示错误信息

    @error_handler
    def runOcrTest(self):
        """线程安全的OCR测试方法"""
        try:
            # 参数验证
            area_tuple_text = self.ocrTupleLineEdit.text().strip()
            if not area_tuple_text:
                self.ocrTestResultLineEdit.setText('错误：坐标值不能为空')
                return
                
            # 安全解析坐标
            try:
                area_tuple = eval(area_tuple_text)
                if not isinstance(area_tuple, tuple) or len(area_tuple) != 4:
                    raise ValueError("坐标必须是4个元素的元组")
                
                # 验证坐标范围
                x1, y1, x2, y2 = area_tuple
                if not all(isinstance(coord, (int, float)) for coord in area_tuple):
                    raise ValueError("所有坐标必须是数字")
                if x1 >= x2 or y1 >= y2:
                    raise ValueError("坐标范围无效：左上角坐标必须小于右下角坐标")
                    
            except Exception as e:
                self.ocrTestResultLineEdit.setText(f'错误：坐标格式不正确 - {str(e)}')
                return
            
            psm_value = self.psmCombox.currentText()
            
            # 创建信号实例
            if not hasattr(self, 'ocr_test_signals'):
                self.ocr_test_signals = self.OCRTestSignals()
            
            # 连接信号到槽函数
            self.ocr_test_signals.update_result.connect(self._update_ocr_result)
            self.ocr_test_signals.update_image.connect(self._update_ocr_image)
            self.ocr_test_signals.update_status.connect(self._update_button_status)
            self.ocr_test_signals.show_error.connect(self._show_ocr_error)
            
            # 停止现有线程
            if hasattr(self, 'ocr_test_thread') and self.ocr_test_thread.isRunning():
                self.ocr_test_thread.quit()
                self.ocr_test_thread.wait()
            
            # 创建并启动线程
            self.ocr_test_thread = self.SafeOCRTestThread(area_tuple, psm_value, self.ocr_test_signals)
            self.ocr_test_thread.start()
            
        except Exception as e:
            self.ocrTestResultLineEdit.setText(f'启动识别失败：{str(e)}')
    # 线程安全的OCR测试线程
    class SafeOCRTestThread(QThread):
        def __init__(self, area_tuple, psm_value, signals, parent=None):
            super().__init__(parent)
            self.area_tuple = area_tuple
            self.psm_value = psm_value
            self.signals = signals
            self.is_running = True
            
        def run(self):
            """在线程中执行OCR识别"""
            try:
                # 禁用按钮
                self.signals.update_status.emit(False)
                
                # 执行OCR识别
                pic_fn = getAreaPic(self.area_tuple)
                ocr_result = doOcr(pic_fn, self.psm_value)
                
                # 通过信号发送结果
                self.signals.update_image.emit(pic_fn)
                self.signals.update_result.emit(str(ocr_result))
                
            except Exception as e:
                # 发送错误信号
                error_msg = f'识别错误！{str(e)}'
                self.signals.show_error.emit(error_msg)
                
            finally:
                # 恢复按钮状态
                self.signals.update_status.emit(True)
        
        def stop(self):
            """停止线程"""
            self.is_running = False
            self.terminate()
            self.wait()

    # 线程安全的UI更新方法
    def _update_ocr_result(self, result):
        """更新OCR结果（线程安全）"""
        self.ocrTestResultLineEdit.setText(result)
    
    def _update_ocr_image(self, image_path):
        """更新OCR图片（线程安全）"""
        try:
            pixmap = QPixmap(image_path)
            self.ocrTestPictureLabel.setPixmap(pixmap)
        except Exception as e:
            print(f"更新图片失败: {e}")
    
    def _update_button_status(self, enabled):
        """更新按钮状态（线程安全）"""
        self.ocrTestBtn.setEnabled(enabled)
    
    def _show_ocr_error(self, error_msg):
        """显示OCR错误（线程安全）"""
        self.ocrTestResultLineEdit.setText(error_msg)

